def injects_for_plan(plan_id: str) -> list:
    """Main-sequence injects for a plan, in seq order (Consequence injects
    are looked up by id only, triggered by a poor decision, not listed here)."""
    return sorted(
        (i for i in INJECTS if i["plan_id"] == plan_id and i["type"] == "Main"),
        key=lambda i: i["seq"],
    )


def find_inject(inject_id: str) -> dict | None:
    return next((i for i in INJECTS if i["inject_id"] == inject_id), None)


def options_for_decision(decision_id: str) -> list:
    return [o for o in DECISION_OPTIONS if o["decision_id"] == decision_id]


def find_option(decision_id: str, option: str) -> dict | None:
    return next((o for o in DECISION_OPTIONS if o["decision_id"] == decision_id and o["option"] == option), None)
